const fs=require('fs')
const first=require('./counter')
const second=require('/workspace/app/counter.js')
const data=require('./data.json')
const fd=fs.openSync('/workspace/io','r+')
const buf=Buffer.alloc(3)
const n=fs.readSync(fd,buf,0,3,1)
fs.writeSync(fd,Buffer.from('XY'),0,2,2)
fs.ftruncateSync(fd,5)
fs.closeSync(fd)
console.log(__filename,__dirname,process.argv[2])
console.log(first===second,first.count,data.answer)
console.log(n,buf.toString(),fs.readFileSync('/workspace/io','utf8'))
console.log(fs.readdirSync('/workspace/app').join(','))
try{fs.statSync('/workspace/missing')}catch(error){console.log(error.code,error.errno)}

const fs=require('fs')
const fsp=require('fs/promises')
;(async()=>{
console.log(fsp===fs.promises)
await fsp.writeFile('/workspace/a.txt','hello')
await fsp.appendFile('/workspace/a.txt','!')
console.log(await fsp.readFile('/workspace/a.txt','utf8'))
await fsp.mkdir('/workspace/d/e',{recursive:true})
console.log((await fsp.readdir('/workspace/d',{withFileTypes:true})).map(e=>e.name+':'+e.isDirectory()).join(','))
console.log((await fsp.stat('/workspace/a.txt')).size)
await fsp.copyFile('/workspace/a.txt','/workspace/d/b.txt')
await fsp.rename('/workspace/d/b.txt','/workspace/d/c.txt')
const fh=await fsp.open('/workspace/d/c.txt','r+')
const buf=Buffer.alloc(3)
const r=await fh.read(buf,0,3,1)
const w=await fh.write('XY',0)
await fh.truncate(4)
await fh.close()
await fh.close()
console.log(r.bytesRead,buf.toString(),w.bytesWritten,fh.fd,await fsp.readFile('/workspace/d/c.txt','utf8'))
await fsp.unlink('/workspace/d/c.txt')
await fsp.rm('/workspace/d',{recursive:true})
console.log(await fsp.stat('/workspace/d').then(()=>'exists',e=>e.code))
try{await fsp.readFile('/workspace/missing')}catch(e){console.log(e.code,e.errno,e.syscall)}
try{fs.readFile('/workspace/a.txt',()=>{})}catch(e){console.log(e.message)}
})()

